/**
 * The attestation must name the resolved tag commit, not the workflow_run
 * default-branch HEAD.
 *
 * GitHub overwrites `GITHUB_*` after a step env is applied, so a step-level
 * `GITHUB_SHA` never reaches the action's `github.context`. The release
 * therefore passes a custom SLSA predicate generated by
 * `scripts/release-provenance.mjs` from the resolved SHA. These tests parse
 * that JSON and execute the exact workflow assertion against a generated
 * `.intoto.jsonl`.
 */
import test from 'node:test';
import assert from 'node:assert/strict';
import { execFileSync } from 'node:child_process';
import { createHash } from 'node:crypto';
import { mkdir, mkdtemp, readFile, rm, writeFile } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import { join } from 'node:path';

import { parseWorkflow } from '../scripts/check-workflows.mjs';
import {
  BUILD_TYPE,
  FALLBACK_BUILDER,
  REPOSITORY_URL,
  builderId,
  parseArguments,
  provenancePredicate,
} from '../scripts/release-provenance.mjs';
import { projectRoot } from './helpers/project-files.mjs';

const RELEASE = join(projectRoot, '.github', 'workflows', 'release.yml');
const SCRIPT = join(projectRoot, 'scripts', 'release-provenance.mjs');
const SHA = 'b'.repeat(40);
const MAIN_HEAD = 'c'.repeat(40);
const TAG = 'v1.0.3';
const VERSION = '1.0.3';

async function releaseJobs() {
  const { workflow } = parseWorkflow(await readFile(RELEASE, 'utf8'));
  const sign = workflow.jobs.sign;
  const build = workflow.jobs.build;
  const attest = sign.steps.find((entry) => String(entry.uses ?? '').startsWith('actions/attest-build-provenance@'));
  const verify = sign.steps.find((entry) => entry.name === 'Prove the provenance binds the tag commit');
  const write = build.steps.find((entry) => entry.name === 'Write the provenance predicate');
  assert.ok(attest, 'the attest action exists');
  assert.ok(verify?.run, 'the provenance assertion exists');
  assert.ok(write?.run, 'the build writes the predicate');
  return { attest, verify, write, build, sign };
}

const { attest: ATTEST, verify: VERIFY, write: WRITE } = await releaseJobs();

function statement({ gitCommit, apkSha, predicate = null }) {
  return {
    _type: 'https://in-toto.io/Statement/v1',
    subject: [{ name: 'drypoint-1.0.3.apk', digest: { sha256: apkSha } }],
    predicateType: 'https://slsa.dev/provenance/v1',
    predicate:
      predicate ??
      provenancePredicate({
        sha: gitCommit,
        tag: TAG,
        version: VERSION,
        builder: 'https://github.com/LLM-4-People/drypoint/actions/runs/1',
      }),
  };
}

async function harness(t, { gitCommit = SHA, apkSha = null, predicate = null } = {}) {
  const root = await mkdtemp(join(tmpdir(), 'drypoint-attest-'));
  t.after(() => rm(root, { recursive: true, force: true }));
  await mkdir(join(root, 'dist'));
  const apk = join(root, 'dist', 'drypoint-1.0.3.apk');
  await writeFile(apk, 'signed apk bytes');
  const digest = createHash('sha256').update(await readFile(apk)).digest('hex');
  const bundle = join(root, 'dist', 'drypoint-1.0.3.apk.intoto.jsonl');
  const payload = Buffer.from(JSON.stringify(statement({ gitCommit, apkSha: apkSha ?? digest, predicate }))).toString('base64');
  await writeFile(
    bundle,
    `${JSON.stringify({
      mediaType: 'application/vnd.dev.sigstore.bundle.v0.3+json',
      dsseEnvelope: { payloadType: 'application/vnd.in-toto+json', payload, signatures: [] },
    })}\n`
  );
  return { root, digest };
}

function runStep(paths, sha = SHA) {
  return execFileSync('bash', ['-c', VERIFY.run], {
    cwd: paths.root,
    env: { ...process.env, VERSION, SHA: sha },
    encoding: 'utf8',
    stdio: 'pipe',
  });
}

test('the predicate binds exactly the resolved tag commit and names the release build', () => {
  const predicate = provenancePredicate({
    sha: SHA,
    tag: TAG,
    version: VERSION,
    builder: 'https://github.com/LLM-4-People/drypoint/actions/runs/42',
  });
  assert.equal(predicate.buildDefinition.buildType, BUILD_TYPE);
  assert.deepEqual(predicate.buildDefinition.externalParameters, { tag: TAG, version: VERSION });
  assert.equal(predicate.buildDefinition.resolvedDependencies.length, 1);
  assert.equal(predicate.buildDefinition.resolvedDependencies[0].uri, `git+${REPOSITORY_URL}@refs/tags/${TAG}`);
  assert.equal(predicate.buildDefinition.resolvedDependencies[0].digest.gitCommit, SHA);
  assert.equal(predicate.runDetails.builder.id, 'https://github.com/LLM-4-People/drypoint/actions/runs/42');
  assert.equal(predicate.runDetails.metadata.invocationId, predicate.runDetails.builder.id);

  assert.throws(() => provenancePredicate({ sha: 'abc', tag: TAG, version: VERSION }), /40-character/);
  assert.throws(() => provenancePredicate({ sha: SHA, tag: 'v1.0', version: VERSION }), /vMAJOR\.MINOR\.PATCH/);
  assert.throws(() => provenancePredicate({ sha: SHA, tag: TAG, version: '1.0' }), /MAJOR\.MINOR\.PATCH/);
  assert.throws(() => provenancePredicate({ sha: SHA, tag: 'v1.0.2', version: VERSION }), /does not match version/);
});

test('the builder id comes from the run and never invents a commit', () => {
  assert.equal(
    builderId({ GITHUB_SERVER_URL: 'https://github.example', GITHUB_REPOSITORY: 'org/repo', GITHUB_RUN_ID: '99' }),
    'https://github.example/org/repo/actions/runs/99'
  );
  assert.equal(builderId({}), FALLBACK_BUILDER);
});

test('the workflow wires the predicate path and has no GITHUB_SHA override', () => {
  assert.equal(ATTEST.with['predicate-type'], 'https://slsa.dev/provenance/v1');
  assert.equal(ATTEST.with['predicate-path'], 'dist/provenance.json');
  assert.equal(ATTEST.with.predicate, undefined);
  assert.equal(ATTEST.env?.GITHUB_SHA, undefined, 'GitHub overwrites GITHUB_* after the step env');
  assert.match(WRITE.run, /node scripts\/release-provenance\.mjs --sha "\$SHA" --tag "\$TAG" --version "\$VERSION" --out dist\/provenance\.json/);
  assert.equal(WRITE['working-directory'], '${{ env.RELEASE_TREE }}');
});

test('the CLI writes parseable JSON and fails nonzero on bad input', async (t) => {
  const root = await mkdtemp(join(tmpdir(), 'drypoint-provenance-'));
  t.after(() => rm(root, { recursive: true, force: true }));
  const out = join(root, 'nested', 'provenance.json');
  const stdout = execFileSync(process.execPath, [SCRIPT, '--sha', SHA, '--tag', TAG, '--version', VERSION, '--out', out], {
    cwd: projectRoot,
    encoding: 'utf8',
    stdio: 'pipe',
    env: { ...process.env, GITHUB_SERVER_URL: 'https://github.com', GITHUB_REPOSITORY: 'LLM-4-People/drypoint', GITHUB_RUN_ID: '7' },
  });
  assert.match(stdout, /provenance: wrote/);
  const predicate = JSON.parse(await readFile(out, 'utf8'));
  assert.equal(predicate.buildDefinition.resolvedDependencies[0].digest.gitCommit, SHA);
  assert.equal(predicate.runDetails.builder.id, 'https://github.com/LLM-4-People/drypoint/actions/runs/7');

  for (const args of [
    ['--sha', 'abc', '--tag', TAG, '--version', VERSION, '--out', join(root, 'bad.json')],
    ['--sha', SHA, '--tag', 'v9.9.9', '--version', VERSION, '--out', join(root, 'bad.json')],
    ['--sha', SHA, '--tag', TAG],
  ]) {
    assert.throws(
      () => execFileSync(process.execPath, [SCRIPT, ...args], { cwd: projectRoot, encoding: 'utf8', stdio: 'pipe' }),
      (error) => error.status !== 0
    );
  }
  assert.deepEqual(parseArguments(['--sha', SHA, '--tag', TAG, '--version', VERSION, '--out', 'x']), {
    sha: SHA,
    tag: TAG,
    version: VERSION,
    out: 'x',
  });
  assert.throws(() => parseArguments(['--sha', SHA]), /--tag is required/);
});

test('the generated predicate passes the workflow assertion', async (t) => {
  const paths = await harness(t);
  const output = runStep(paths);
  assert.match(output, new RegExp(`provenance binds ${paths.digest} to ${SHA}`));
});

test('a predicate carrying the default-branch HEAD fails the release', async (t) => {
  const paths = await harness(t, { gitCommit: MAIN_HEAD });
  assert.throws(
    () => runStep(paths),
    (error) => error.status !== 0 && /does not bind the signed APK to the resolved commit/.test(`${error.stdout}${error.stderr}`),
    'the workflow_run default-branch HEAD must not satisfy the binding'
  );
});

test('a predicate for a different APK digest fails the release', async (t) => {
  const paths = await harness(t, { apkSha: 'd'.repeat(64) });
  assert.throws(() => runStep(paths), (error) => error.status !== 0, 'the subject digest is part of the binding');
});

test('a predicate with zero or two resolved dependencies fails the release', async (t) => {
  for (const dependencies of [
    [],
    [
      { uri: `git+${REPOSITORY_URL}@refs/tags/${TAG}`, digest: { gitCommit: SHA } },
      { uri: `git+${REPOSITORY_URL}@refs/heads/main`, digest: { gitCommit: MAIN_HEAD } },
    ],
  ]) {
    const predicate = provenancePredicate({ sha: SHA, tag: TAG, version: VERSION });
    predicate.buildDefinition.resolvedDependencies = dependencies;
    const paths = await harness(t, { predicate });
    assert.throws(() => runStep(paths), (error) => error.status !== 0, `${dependencies.length} dependencies fails`);
  }
});

test('a missing bundle fails closed', async (t) => {
  const paths = await harness(t);
  await rm(join(paths.root, 'dist', 'drypoint-1.0.3.apk.intoto.jsonl'));
  assert.throws(() => runStep(paths), (error) => error.status !== 0);
});
